+func updateMatchQueries(q query.Query, field string) {
+	switch t := q.(type) {
+	case *query.MatchQuery:
+		if t.Field == "" {
+			t.Field = field
+		}
+	case *query.MatchPhraseQuery:
+		if t.Field == "" {
+			t.Field = field
+		}
+	case *query.TermQuery:
+		if t.Field == "" {
+			t.Field = field
+		}
+	case *query.PrefixQuery:
+		if t.Field == "" {
+			t.Field = field
+		}
+	case *query.RegexpQuery:
+		if t.Field == "" {
+			t.Field = field
+		}
+	case *query.WildcardQuery:
+		if t.Field == "" {
+			t.Field = field
+		}
+	case *query.BooleanQuery:
+		if t.Must != nil {
+			for _, sub := range t.Must.Disjuncts {
+				updateMatchQueries(sub, field)
+			}
+		}
+		if t.Should != nil {
+			for _, sub := range t.Should.Disjuncts {
+				updateMatchQueries(sub, field)
+			}
+		}
+		if t.MustNot != nil {
+			for _, sub := range t.MustNot.Disjuncts {
+				updateMatchQueries(sub, field)
+			}
+		}
+	case *query.QueryStringQuery:
+		if t.DefaultField == "" {
+			t.DefaultField = field
+		}
+	}
+}
+
 func (q *QueryStringQuery) Searcher(ctx context.Context, i index.IndexReader, m mapping.IndexMapping, options search.SearcherOptions) (search.Searcher, error) {
 	newQuery, err := parseQuerySyntax(q.Query)
 	if err != nil {
 		return nil, err
 	}
+
+	defaultField := q.DefaultField
+	if defaultField == "" {
+		defaultField = m.DefaultSearchField()
+	}
+
+	if defaultField != "" {
+		updateMatchQueries(newQuery, defaultField)
+	}
+
 	return newQuery.Searcher(ctx, i, m, options)
 }

